/** 计算攻击属性对某只宝可梦（可双属性）的总倍率 */
export function typeMultiplier(attackType, defenderTypes) {
  const row = TYPE_CHART[attackType] || {}
  const defs = (defenderTypes || []).filter(Boolean)
  if (!defs.length) return 1
  return defs.reduce((mul, d) => mul * (row[d] === undefined ? 1 : row[d]), 1)
}

