/** 根据宝可梦主属性推荐 4 个招式（供对战使用） */
export function movesFor(p) {
  const main = (p && p.category) || '一般'
  const same = MOVES.filter(m => m.type === main && m.power > 0)
  const other = MOVES.filter(m => m.type !== main && m.power > 0)
  const list = [...same, ...other].slice(0, 4)
  return list.length ? list : MOVES.slice(0, 4)
}

// ============ 技能学习 / 升级学招（原著：招式学习器按属性对应）============
/** 招式名 → 招式对象（读取存档中持久化的技能名） */
export function movesFromNames(names) {
  if (!Array.isArray(names)) return []
  const out = []
  for (const n of names) {
    const m = MOVES.find(x => x.name === n)
    if (m && !out.some(x => x.name === m.name)) out.push(m)
  }
  return out
}

/** 按属性取可学招式：本属性招式 + 一般属性通用招式 */
export function movesByType(type, includeNormal = true) {
  return MOVES.filter(m => m.type === type || (includeNormal && m.type === '一般'))
}

/** 一只宝可梦可学的全部招式（主/副属性招式优先，一般属性通用招式兜底） */
export function learnableMoves(p) {
  const types = [p && p.category, p && p.category2].filter(Boolean)
  const seen = new Set()
  const out = []
  for (const t of types) {
    for (const m of movesByType(t, false)) {
      if (!seen.has(m.name)) { seen.add(m.name); out.push(m) }
    }
  }
  for (const m of movesByType('一般')) {
    if (!seen.has(m.name)) { seen.add(m.name); out.push(m) }
  }
  return out
}

/** 读取宝可梦已学技能；无持久化技能时退回按属性推荐 */
export function movesForFighter(fighter, dexItem) {
  const saved = movesFromNames(fighter && fighter.moves)
  if (saved.length) return saved.slice(0, 4)
  return movesFor(dexItem || fighter || { category: '一般' })
}
